append_tile_error() {
    local cycle_number="$1"
    local status="$2"
    local lat="$3"
    local lon="$4"
    local center="$5"
    local route_command="$6"

    printf '%s | script=runSpain15 | cycle=%s/%s | lat=%s lon=%s center=%s | route=%s | reason=tile_failed_status_%s\n' \
        "$(date --iso-8601=seconds)" \
        "$cycle_number" \
        "$TOTAL_TILES" \
        "$lat" \
        "$lon" \
        "$center" \
        "$route_command" \
        "$status" >> "$ERRORS_LOG" || true
}

