build_ordered_tiles() {
    local lat
    local lon
    local center_lat
    local center_lon
    local distance_sq

    for lat in "${LATS[@]}"; do
        for lon in "${LONS[@]}"; do
            if ! should_download "$lat" "$lon"; then
                continue
            fi

            center_lat="$(awk -v value="$lat" -v offset="$TILE_CENTER_OFFSET" 'BEGIN { printf "%.6f", value + offset }')"
            center_lon="$(awk -v value="$lon" -v offset="$TILE_CENTER_OFFSET" 'BEGIN { printf "%.6f", value + offset }')"
            distance_sq="$(awk \
                -v lat="$center_lat" \
                -v lon="$center_lon" \
                -v ref_lat="$ORDER_REFERENCE_LAT" \
                -v ref_lon="$ORDER_REFERENCE_LON" \
                'BEGIN {
                    d_lat = lat - ref_lat
                    d_lon = lon - ref_lon
                    printf "%.12f", (d_lat * d_lat) + (d_lon * d_lon)
                }')"
            printf '%s\t%s\t%s\t%s\n' "$distance_sq" "$lat" "$lon" "$center_lat,$center_lon"
        done
    done | sort -t $'\t' -k1,1n -k2,2n -k3,3n
}

mapfile -t ORDERED_TILES < <(build_ordered_tiles)
readonly TOTAL_TILES="${#ORDERED_TILES[@]}"

for index in "${!ORDERED_TILES[@]}"; do
    cycle_number=$((index + 1))

    if (( cycle_number < START_FROM_TILE )); then
        continue
    fi

    IFS=$'\t' read -r _distance_sq LAT LON TILE_CENTER <<< "${ORDERED_TILES[$index]}"
    route_command="./run.sh zigzag $LAT $LON 7000 100 3000 0.44 0.38"

    printf '[runSpain15][INFO] Starting cycle %d/%d (tile %d onward) at lat=%s lon=%s center=%s.\n' \
        "$cycle_number" "$TOTAL_TILES" "$START_FROM_TILE" "$LAT" "$LON" "$TILE_CENTER"

    pipeline_tmp_dir="${PIPELINE_TMP_DIR:-/media/ramdisk}"
    mkdir -p "$pipeline_tmp_dir"
    run_log="$(mktemp "$pipeline_tmp_dir/runSpain15.runFullProcess.XXXXXX")"
    if (
        cp -- "$MY_PLACES_DIR/myplaces.kml.bak" "$MY_PLACES_DIR/myplaces.kml" &&
        cd "$PATH_PLANNER_DIR" &&
        ./run.sh zigzag "$LAT" "$LON" 7000 100 3000 0.44 0.38 &&
        cd "$PROJECT_DIR" &&
        ./scripts/runFullProcess.sh \
            --route-command "$route_command"
    ) > >(tee "$run_log" | grep --line-buffered '\[PHASE\]') 2>&1; then
        grep -v '\[PHASE\]' "$run_log" || true
        printf '[runSpain15][INFO] Finished cycle %d/%d at lat=%s lon=%s.\n' \
            "$cycle_number" "$TOTAL_TILES" "$LAT" "$LON"
        rm -f -- "$run_log"
    else
        status=$?
        # A failed tile must not stop the batch nor emit its failure output.
        append_tile_error "$cycle_number" "$status" "$LAT" "$LON" "$TILE_CENTER" "$route_command"
        rm -f -- "$run_log"
        pkill -9 google-earth >/dev/null 2>&1 || true
    fi
done
